"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[25401],{90297(e,a,o){o.r(a),o.d(a,{assets:()=>c,contentTitle:()=>s,default:()=>u,frontMatter:()=>t,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"cursos/arquitectura-software/modulos/gobierno-estandares/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 es el \\"Technology Radar\\" de ThoughtWorks en profundidad y c\xf3mo implementaron Neal Ford y Rebecca Parsons el concepto de \\"Blip\\" para evaluar tecnolog\xedas emergentes?","source":"@site/docs/cursos/arquitectura-software/modulos/14-gobierno-estandares/cuestionario.md","sourceDirName":"cursos/arquitectura-software/modulos/14-gobierno-estandares","slug":"/cursos/arquitectura-software/modulos/gobierno-estandares/cuestionario","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/gobierno-estandares/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/gobierno-estandares/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/gobierno-estandares/ejercicio"}}');var n=o(74848),i=o(28453);const t={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},s=void 0,c={},l=[{value:"2. [Investigar] \xbfQu\xe9 es el &quot;Technology Radar&quot; de ThoughtWorks en profundidad y c\xf3mo implementaron Neal Ford y Rebecca Parsons el concepto de &quot;Blip&quot; para evaluar tecnolog\xedas emergentes?",id:"2-investigar-qu\xe9-es-el-technology-radar-de-thoughtworks-en-profundidad-y-c\xf3mo-implementaron-neal-ford-y-rebecca-parsons-el-concepto-de-blip-para-evaluar-tecnolog\xedas-emergentes",level:3},{value:"3. [Investigar] \xbfQu\xe9 es &quot;Team Topologies&quot; aplicado a gobierno de arquitectura y c\xf3mo Matthew Skelton propone la &quot;Platform Team&quot; como mecanismo de gobernanza sin burocracia?",id:"3-investigar-qu\xe9-es-team-topologies-aplicado-a-gobierno-de-arquitectura-y-c\xf3mo-matthew-skelton-propone-la-platform-team-como-mecanismo-de-gobernanza-sin-burocracia",level:3},{value:"4. [Investigar] \xbfQu\xe9 es el est\xe1ndar ISO/IEC/IEEE 42010:2022 (&quot;Architecture Description&quot;) y c\xf3mo formaliza conceptos que la clase trata informalmente?",id:"4-investigar-qu\xe9-es-el-est\xe1ndar-isoiecieee-420102022-architecture-description-y-c\xf3mo-formaliza-conceptos-que-la-clase-trata-informalmente",level:3},{value:"5. [Conectar] La clase presenta TOGAF ADM como ciclo de arquitectura empresarial. \xbfC\xf3mo se relaciona TOGAF con el &quot;Architecture Repository&quot; y el &quot;Enterprise Continuum&quot; que son esenciales para reutilizaci\xf3n?",id:"5-conectar-la-clase-presenta-togaf-adm-como-ciclo-de-arquitectura-empresarial-c\xf3mo-se-relaciona-togaf-con-el-architecture-repository-y-el-enterprise-continuum-que-son-esenciales-para-reutilizaci\xf3n",level:3},{value:"6. [Conectar] La clase cubre Tech Radar con 4 categor\xedas. \xbfC\xf3mo se relaciona con el &quot;Hype Cycle&quot; de Gartner y por qu\xe9 ThoughtWorks rechaza expl\xedcitamente el Hype Cycle como herramienta?",id:"6-conectar-la-clase-cubre-tech-radar-con-4-categor\xedas-c\xf3mo-se-relaciona-con-el-hype-cycle-de-gartner-y-por-qu\xe9-thoughtworks-rechaza-expl\xedcitamente-el-hype-cycle-como-herramienta",level:3},{value:"7. [Conectar] La clase describe roles de arquitecto (Soluci\xf3n, Enterprise, T\xe9cnico, Dominio). \xbfC\xf3mo se alinea esto con el &quot;Architect Skills Framework&quot; de Gregor Hohpe y el perfil &quot;T-shaped&quot; que propone?",id:"7-conectar-la-clase-describe-roles-de-arquitecto-soluci\xf3n-enterprise-t\xe9cnico-dominio-c\xf3mo-se-alinea-esto-con-el-architect-skills-framework-de-gregor-hohpe-y-el-perfil-t-shaped-que-propone",level:3},{value:"8. [Cuestionar] \xbfEs TOGAF irrelevante en la era de DevOps y microservicios? La cr\xedtica de que TOGAF es &quot;waterfall architecture&quot; en un mundo \xe1gil.",id:"8-cuestionar-es-togaf-irrelevante-en-la-era-de-devops-y-microservicios-la-cr\xedtica-de-que-togaf-es-waterfall-architecture-en-un-mundo-\xe1gil",level:3},{value:"9. [Cuestionar] \xbfDebe el Architecture Review Board (ARB) tener autoridad de veto o solo poder consultivo? El debate entre gobernanza fuerte y autonom\xeda de equipos.",id:"9-cuestionar-debe-el-architecture-review-board-arb-tener-autoridad-de-veto-o-solo-poder-consultivo-el-debate-entre-gobernanza-fuerte-y-autonom\xeda-de-equipos",level:3},{value:"10. [Cuestionar] \xbfLa estandarizaci\xf3n tecnol\xf3gica (un solo lenguaje, un solo framework) es disciplina o rigidez que frena la innovaci\xf3n? El debate heterogeneidad controlada.",id:"10-cuestionar-la-estandarizaci\xf3n-tecnol\xf3gica-un-solo-lenguaje-un-solo-framework-es-disciplina-o-rigidez-que-frena-la-innovaci\xf3n-el-debate-heterogeneidad-controlada",level:3}];function d(e){const a={em:"em",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-el-technology-radar-de-thoughtworks-en-profundidad-y-c\xf3mo-implementaron-neal-ford-y-rebecca-parsons-el-concepto-de-blip-para-evaluar-tecnolog\xedas-emergentes",children:'2. [Investigar] \xbfQu\xe9 es el "Technology Radar" de ThoughtWorks en profundidad y c\xf3mo implementaron Neal Ford y Rebecca Parsons el concepto de "Blip" para evaluar tecnolog\xedas emergentes?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase present\xf3 Tech Radar como 4 categor\xedas est\xe1ticas, pero su valor real es el tracking din\xe1mico de tendencias. ThoughtWorks publica la metodolog\xeda en thoughtworks.com/radar. Para E-Commerce Platform, un radar interno tracking el movimiento de tecnolog\xedas (Spring Boot \u2192 Adopt estable, WebFlux \u2192 Trial en ascenso) ayudar\xeda a anticipar cu\xe1ndo migrar."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"3-investigar-qu\xe9-es-team-topologies-aplicado-a-gobierno-de-arquitectura-y-c\xf3mo-matthew-skelton-propone-la-platform-team-como-mecanismo-de-gobernanza-sin-burocracia",children:'3. [Investigar] \xbfQu\xe9 es "Team Topologies" aplicado a gobierno de arquitectura y c\xf3mo Matthew Skelton propone la "Platform Team" como mecanismo de gobernanza sin burocracia?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Matthew Skelton y Manuel Pais, en ",(0,n.jsx)(a.em,{children:"Team Topologies"})," (2019), proponen que la gobernanza arquitect\xf3nica no debe ser un comit\xe9 (ARB) sino una ",(0,n.jsx)(a.strong,{children:"Platform Team"}),' que construye y mantiene una Internal Developer Platform (IDP). La plataforma impone restricciones arquitect\xf3nicas de forma habilitante, no restrictiva: en lugar de que el ARB diga "no uses NoSQL", la plataforma provee PostgreSQL como servicio gestionado con APIs simples, y si un equipo quiere MongoDB, la plataforma eval\xfaa si incorporarlo como opci\xf3n soportada. La gobernanza se ejerce a trav\xe9s de "paved roads" (caminos pavimentados): la plataforma hace que la opci\xf3n correcta sea la m\xe1s f\xe1cil, y si un equipo elige desviarse, asume el costo operacional.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Skelton y Pais revolucionaron el concepto de gobernanza al cambiar de "prohibir" a "habilitar." La clase present\xf3 ARB como mecanismo de revisi\xf3n, pero Team Topologies propone que la plataforma sea el mecanismo de gobernanza. Netflix y Spotify implementan esto: sus plataformas internas no proh\xedben, pero hacen que el "golden path" sea trivial, y salirse requiere justificaci\xf3n.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-el-est\xe1ndar-isoiecieee-420102022-architecture-description-y-c\xf3mo-formaliza-conceptos-que-la-clase-trata-informalmente",children:'4. [Investigar] \xbfQu\xe9 es el est\xe1ndar ISO/IEC/IEEE 42010:2022 ("Architecture Description") y c\xf3mo formaliza conceptos que la clase trata informalmente?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': ISO/IEC/IEEE 42010:2022 (reemplazando la versi\xf3n 2011) es el est\xe1ndar internacional para descripci\xf3n de arquitectura. Formaliza conceptos que la clase usa informalmente: define "Architecture Viewpoint" (convenciones para construir una vista), "Architecture View" (vista de una arquitectura desde un viewpoint), "Architecture Model" (representaci\xf3n de aspectos de la arquitectura), "Stakeholder" (parte interesada con concerns), "Concern" (inter\xe9s en el sistema), y "Architecture Rationale" (justificaci\xf3n de decisiones). La relaci\xf3n con el C4: C4 Nivel 1 es un viewpoint de Contexto; Nivel 2 es un viewpoint de Container; etc. ISO 42010 no prescribe qu\xe9 viewpoints usar, pero requiere que se declaren expl\xedcitamente y se vinculen a stakeholders y concerns.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase present\xf3 conceptos como stakeholder, vista y diagrama sin citar el est\xe1ndar internacional que los formaliza. En contextos de compliance (defensa, aeroespacial, gobierno), la conformidad con ISO 42010 puede ser un requisito contractual. Para el proyecto final, estructurar la documentaci\xf3n seg\xfan ISO 42010 ser\xeda un diferenciador de calidad profesional."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"5-conectar-la-clase-presenta-togaf-adm-como-ciclo-de-arquitectura-empresarial-c\xf3mo-se-relaciona-togaf-con-el-architecture-repository-y-el-enterprise-continuum-que-son-esenciales-para-reutilizaci\xf3n",children:'5. [Conectar] La clase presenta TOGAF ADM como ciclo de arquitectura empresarial. \xbfC\xf3mo se relaciona TOGAF con el "Architecture Repository" y el "Enterprise Continuum" que son esenciales para reutilizaci\xf3n?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": TOGAF define el ",(0,n.jsx)(a.strong,{children:"Architecture Repository"})," como un repositorio centralizado de artefactos arquitect\xf3nicos reutilizables: Architecture Metamodel, Architecture Capability, Architecture Landscape, Standards Information Base (SIB), Reference Library, y Governance Log. El ",(0,n.jsx)(a.strong,{children:"Enterprise Continuum"}),' es un modelo conceptual que va desde arquitecturas gen\xe9ricas (Foundation Architectures) a espec\xedficas (Organization-Specific Architectures). La relaci\xf3n con la clase: cuando escrib\xeds un ADR sobre PostgreSQL, deber\xeda referenciar el SIB (Standards Information Base) que dice "PostgreSQL es la base de datos est\xe1ndar aprobada." Cuando dise\xf1\xe1s un bounded context, deber\xeda existir en el Architecture Landscape junto con los dem\xe1s. Sin repositorio, cada proyecto reinventa decisiones.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase present\xf3 ADM como ciclo y Tech Radar como herramienta, pero no los conect\xf3 con repositorio y continuo. El valor real de TOGAF no es el ciclo ADM \u2014es la infraestructura de reutilizaci\xf3n (Repository + Continuum) que evita que cada equipo tome decisiones inconsistentes."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"6-conectar-la-clase-cubre-tech-radar-con-4-categor\xedas-c\xf3mo-se-relaciona-con-el-hype-cycle-de-gartner-y-por-qu\xe9-thoughtworks-rechaza-expl\xedcitamente-el-hype-cycle-como-herramienta",children:'6. [Conectar] La clase cubre Tech Radar con 4 categor\xedas. \xbfC\xf3mo se relaciona con el "Hype Cycle" de Gartner y por qu\xe9 ThoughtWorks rechaza expl\xedcitamente el Hype Cycle como herramienta?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Gartner Hype Cycle mapea tecnolog\xedas seg\xfan visibilidad medi\xe1tica y expectativas en 5 fases: Innovation Trigger, Peak of Inflated Expectations, Trough of Disillusionment, Slope of Enlightenment, Plateau of Productivity. ThoughtWorks rechaza el Hype Cycle como herramienta de decisi\xf3n arquitect\xf3nica porque: (1) est\xe1 basado en percepci\xf3n de mercado y hype, no en experiencia de uso real en proyectos, (2) no distingue entre tecnolog\xeda prometedora y tecnolog\xeda lista para producci\xf3n, y (3) tiene un sesgo hacia tecnolog\xedas con marketing ruidoso sobre tecnolog\xedas s\xf3lidas pero menos visibles. El Tech Radar se basa en experiencia real de los consultores de ThoughtWorks en proyectos con clientes, no en percepci\xf3n de mercado."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": Neal Ford y Rebecca Parsons han explicado esta diferencia en charlas y en la metodolog\xeda del Radar. La clase no mencion\xf3 el Hype Cycle, pero es importante entender por qu\xe9 el Tech Radar es superior para decisiones arquitect\xf3nicas: eval\xfaa tecnolog\xedas en contexto de uso real, no en abstracto."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"7-conectar-la-clase-describe-roles-de-arquitecto-soluci\xf3n-enterprise-t\xe9cnico-dominio-c\xf3mo-se-alinea-esto-con-el-architect-skills-framework-de-gregor-hohpe-y-el-perfil-t-shaped-que-propone",children:'7. [Conectar] La clase describe roles de arquitecto (Soluci\xf3n, Enterprise, T\xe9cnico, Dominio). \xbfC\xf3mo se alinea esto con el "Architect Skills Framework" de Gregor Hohpe y el perfil "T-shaped" que propone?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": Gregor Hohpe, en ",(0,n.jsx)(a.em,{children:"The Software Architect Elevator"})," y en charlas, propone que el arquitecto moderno debe ser ",(0,n.jsx)(a.strong,{children:"T-shaped"}),': profundidad en una o dos \xe1reas t\xe9cnicas (la barra vertical de la T) y amplitud en m\xfaltiples disciplinas \u2014negocio, operaciones, seguridad, datos, comunicaci\xf3n\u2014 (la barra horizontal). Hohpe critica la especializaci\xf3n extrema (arquitecto que solo hace TOGAF, o solo hace DDD, o solo hace infraestructura) porque la arquitectura real requiere conectar todas las capas. El framework de habilidades de Hohpe incluye: Technology, Business Strategy, Communication, Organizational Dynamics, y Systems Thinking. Los roles de la clase (Soluci\xf3n, Enterprise) son "especializaciones" que Hohpe considera insuficientes sin la visi\xf3n sist\xe9mica.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': Hohpe enfatiza que el mayor riesgo en arquitectura no es t\xe9cnico \u2014es la desconexi\xf3n entre negocio y tecnolog\xeda. El arquitecto que solo sabe de microservicios pero no entiende el P&L de la empresa, toma decisiones que no sobreviven el primer trimestre. La clase present\xf3 roles especializados, pero Hohpe argumenta que el "arquitecto de soluci\xf3n" moderno debe tener la amplitud del "arquitecto de negocio."']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"8-cuestionar-es-togaf-irrelevante-en-la-era-de-devops-y-microservicios-la-cr\xedtica-de-que-togaf-es-waterfall-architecture-en-un-mundo-\xe1gil",children:'8. [Cuestionar] \xbfEs TOGAF irrelevante en la era de DevOps y microservicios? La cr\xedtica de que TOGAF es "waterfall architecture" en un mundo \xe1gil.'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase present\xf3 TOGAF como framework de referencia sin discutir su relevancia actual. La realidad: TOGAF sigue siendo relevante en gobierno, defensa y banca tradicional; es irrelevante en startups y empresas nativas digitales. Muchos arquitectos obtienen certificaci\xf3n TOGAF por su valor curricular pero no lo aplican en su trabajo diario."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"9-cuestionar-debe-el-architecture-review-board-arb-tener-autoridad-de-veto-o-solo-poder-consultivo-el-debate-entre-gobernanza-fuerte-y-autonom\xeda-de-equipos",children:"9. [Cuestionar] \xbfDebe el Architecture Review Board (ARB) tener autoridad de veto o solo poder consultivo? El debate entre gobernanza fuerte y autonom\xeda de equipos."}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": En gobernanza fuerte (modelo tradicional, banca, gobierno), el ARB tiene poder de veto: nadie deploya a producci\xf3n sin aprobaci\xf3n del ARB. Esto garantiza consistencia pero crea cuellos de botella y desalienta innovaci\xf3n. En gobernanza consultiva (modelo \xe1gil, Spotify, Netflix), el ARB (o Guild) recomienda y documenta, pero los equipos toman la decisi\xf3n final \u2014si un equipo decide desviarse, lo documenta en un ADR justificando el trade-off. La evidencia de ThoughtWorks y DevOps Research (DORA, State of DevOps) muestra que los equipos con m\xe1s autonom\xeda tienen mejor desempe\xf1o. Pero en sistemas cr\xedticos (PCI-DSS, HIPAA), la gobernanza fuerte puede ser un requisito regulatorio."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase present\xf3 ARB como comit\xe9 que "revisa y aprueba," sin discutir el espectro de autoridad. La decisi\xf3n correcta depende del contexto: en una fintech, el ARB probablemente necesita poder de veto para decisiones de seguridad; en una startup de e-commerce, el ARB deber\xeda ser consultivo.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"10-cuestionar-la-estandarizaci\xf3n-tecnol\xf3gica-un-solo-lenguaje-un-solo-framework-es-disciplina-o-rigidez-que-frena-la-innovaci\xf3n-el-debate-heterogeneidad-controlada",children:"10. [Cuestionar] \xbfLa estandarizaci\xf3n tecnol\xf3gica (un solo lenguaje, un solo framework) es disciplina o rigidez que frena la innovaci\xf3n? El debate heterogeneidad controlada."}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": La estandarizaci\xf3n estricta (solo Java + Spring Boot) reduce complejidad operacional, facilita el movimiento de desarrolladores entre equipos y simplifica el tooling. La heterogeneidad controlada (el equipo elige dentro de un conjunto aprobado) permite innovaci\xf3n y adecuaci\xf3n al problema. El debate: Netflix (que estandariza fuertemente) vs Amazon (que permite heterogeneidad). La evidencia de DORA (Accelerate State of DevOps, 2023) muestra que no hay correlaci\xf3n directa entre estandarizaci\xf3n y desempe\xf1o; lo que importa es que el equipo tenga autonom\xeda sobre sus herramientas dentro de constraints claros. La postura pragm\xe1tica: estandarizar lo que no aporta diferenciaci\xf3n (CI/CD, logging, seguridad) y permitir elecci\xf3n en lo que s\xed (lenguaje de dominio espec\xedfico, base de datos)."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase present\xf3 estandarizaci\xf3n como buena pr\xe1ctica, pero la investigaci\xf3n moderna (Nicole Forsgren, Jez Humble, Gene Kim en ",(0,n.jsx)(a.em,{children:"Accelerate"}),") muestra que la autonom\xeda de herramientas es un predictor de desempe\xf1o. La clave es el balance: constraints en cross-cutting concerns; libertad en el dominio."]}),"\n",(0,n.jsx)(a.hr,{})]})}function u(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},28453(e,a,o){o.d(a,{R:()=>t,x:()=>s});var r=o(96540);const n={},i=r.createContext(n);function t(e){const a=r.useContext(i);return r.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function s(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:t(e.components),r.createElement(i.Provider,{value:a},e.children)}}}]);